import { useNavigate } from "react-router-dom";

const SimpleTopbar = ({ right }) => {
  const navigate = useNavigate();
  return (
    <div className="h-14 bg-white border-b border-gray-200 flex items-center justify-between px-8">
      <div className="flex items-center gap-2 cursor-pointer" onClick={() => navigate("/")}>
        <div className="w-8 h-8 bg-navy rounded-lg flex items-center justify-center text-white font-bold text-sm">A</div>
        <span className="font-semibold text-gray-900">WorkBridge DZ</span>
      </div>
      {right}
    </div>
  );
};

export function ForgotPasswordPage() {
  const navigate = useNavigate();

  const stepItems = [
    { n: 1, label: "Email", active: true, done: false },
    { n: 2, label: "Verification", active: false, done: false },
    { n: 3, label: "New Password", active: false, done: false },
  ];

  return (
    <div className="min-h-screen bg-cream flex flex-col">
      <SimpleTopbar right={
        <button onClick={() => navigate("/sign-in")} className="text-sm text-gray-400 hover:text-gray-900">
          ← Back to Sign In
        </button>
      } />

      <div className="flex-1 flex flex-col items-center justify-center px-6 py-10 text-center">
        <div className="w-14 h-14 bg-red/10 rounded-2xl flex items-center justify-center text-2xl mb-6">🔒</div>

        <h1 className="font-serif text-3xl font-normal mb-3">Forgot your password?</h1>
        <p className="text-sm text-gray-500 max-w-sm leading-relaxed mb-8">
          No worries. Enter the email address linked to your account and we'll send you a reset link.
        </p>

        {/* Steps */}
        <div className="flex items-center gap-3 mb-8">
          {stepItems.map((s, i) => (
            <div key={s.n} className="flex items-center gap-2">
              {i > 0 && <div className="w-14 h-px bg-gray-200" />}
              <div className={`w-7 h-7 rounded-full border flex items-center justify-center text-xs font-medium
                ${s.active ? "bg-navy border-navy text-white" : "border-gray-200 text-gray-400 bg-white"}`}>
                {s.n}
              </div>
              <span className={`text-sm ${s.active ? "text-gray-900 font-medium" : "text-gray-400"}`}>{s.label}</span>
            </div>
          ))}
        </div>

        <div className="bg-white rounded-2xl border border-gray-200 p-8 w-full max-w-sm">
          <label className="block text-sm font-medium mb-2 text-left">Email Address</label>
          <input className="w-full px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm mb-1 outline-none focus:border-navy focus:bg-white" placeholder="you@example.com" />
          <p className="text-xs text-gray-400 mb-5 text-left">We'll send a reset link to this address.</p>

          <div className="flex items-center gap-3 bg-cream border border-gray-200 rounded-xl px-4 py-3 mb-5">
            <input type="checkbox" className="w-4 h-4" />
            <span className="text-sm text-gray-700 flex-1">I'm not a robot</span>
            <div className="text-right text-[10px] text-gray-400 leading-tight">reCAPTCHA<br />Privacy · Terms</div>
          </div>

          <button className="w-full py-3.5 bg-red text-white rounded-full text-sm font-medium hover:bg-red-dark transition-all" onClick={() => navigate("/verify-code")}>
            Send Reset Link →
          </button>

          <p className="text-sm text-gray-500 text-center mt-4">
            Remember your password?{" "}
            <span className="text-navy underline cursor-pointer" onClick={() => navigate("/sign-in")}>Sign in</span>
          </p>
        </div>
      </div>
    </div>
  );
}

export default ForgotPasswordPage;
